 for(const id of o.value.legacy_unknown_reservations){const slot=tx.get('slots',id),original=seal.value.legacy_reservation_refs.find(r=>r.id===id),applicability=seal.value.reservation_applicability.find(r=>r.slot_ref.id===id);need(slot?.value.kind==='legacy_origin_reservation'&&slot.value.status==='unknown'&&slot.value.release_authority===false&&same(ref('slots',slot),original)&&applicability&&same(applicability.slot_ref,original),'ORIGIN_RESERVATION_CHANGED');if(!readonly&&applicability.scopes.some(s=>overlap(s,scope)))need(false,'ORIGIN_UNCERTAIN_SCOPE_OVERLAP');}
